mapper.update:
update setmeal
set status=#{status},
    update_time=NOW(),
    update_user=${@com.dingdingcatering.context.BaseContext@getCurrentId()}
where id = #{id}

update setmeal
category_id=#{categoryId}, name=#{name}, description=#{description}, image=#{image}, price=#{price}, status=#{status}, update_time=#{updateTime}, update_user=#{updateUser}, update_employee_name=#{updateEmployeeName},
where id = #{id}

mapper.delete:
delete sdf from setmeal_dish_flavor sdf
inner join setmeal_dish sd on sdf.setmeal_dish_id = sd.id
where sd.setmeal_id = #{setmealId}

mapper.select:
select s.id,s.category_id,s.name,s.price,s.status,s.description,s.image,s.update_time,c.name as categoryName, s.create_employee_name, s.update_employee_name, sd.id as setmeal_dish_id, sd.setmeal_id, sd.dish_id, sd.name as dish_name, sd.price as dish_price, sd.copies, sdf.id as sdf_id, sdf.setmeal_dish_id as sdf_setmeal_dish_id, sdf.flavor_id as sdf_flavor_id, sdf.flavor_value as sdf_flavor_value, sdf.flavor_name as sdf_flavor_name, sdf.value_list as sdf_value_list from setmeal s left join category c on c.id = s.category_id left join setmeal_dish sd on sd.setmeal_id = s.id left join setmeal_dish_flavor sdf on sd.id = sdf.setmeal_dish_id
and s.name like concat('%',#{name},'%') and s.status=#{status} and s.category_id =#{categoryId}
order by s.update_time desc, sd.id

select name
from setmeal
where category_id = #{categoryId}

select dish_id
from setmeal_dish
where setmeal_id = #{id};

select s.name from setmeal s where s.id in

    #{id}

and status = ${@com.dingdingcatering.constant.StatusConstant@ENABLE}

select sd.setmeal_id, sd.id, sd.dish_id, sd.name as dish_name, sd.price as dish_price, sd.copies, sdf.id as sdf_id, sdf.setmeal_dish_id as sdf_setmeal_dish_id, sdf.flavor_id as sdf_flavor_id, sdf.flavor_value as sdf_flavor_value, sdf.flavor_name as sdf_flavor_name, sdf.value_list as sdf_value_list from setmeal_dish sd left join setmeal_dish_flavor sdf on sd.id = sdf.setmeal_dish_id where sd.setmeal_id in
#{id}
order by sd.setmeal_id, sd.id

select s.id, s.category_id, s.name, s.price, s.status, s.description, s.image, s.update_time, c.name as categoryName, s.create_employee_name as createEmployeeName, s.update_employee_name as updateEmployeeName from setmeal s left join category c on c.id = s.category_id
and s.name like concat('%',#{name},'%') and s.status=#{status} and s.category_id =#{categoryId}
order by s.update_time desc

select s.id, s.category_id, s.name, s.price, s.status, s.description, s.image, s.update_time, c.name as category_name, s.create_employee_name, s.update_employee_name, sd.id as setmeal_dish_id, sd.setmeal_id, sd.dish_id, sd.name as dish_name, sd.price as dish_price, sd.copies, sdf.id as sdf_id, sdf.setmeal_dish_id as sdf_setmeal_dish_id, sdf.flavor_id as sdf_flavor_id, sdf.flavor_value as sdf_flavor_value, sdf.flavor_name as sdf_flavor_name, sdf.value_list as sdf_value_list from setmeal s left join category c on c.id = s.category_id left join setmeal_dish sd on sd.setmeal_id = s.id left join setmeal_dish_flavor sdf on sd.id = sdf.setmeal_dish_id where s.id in
#{id}
order by s.id, sd.id
